{
  "story": "How does posting a journal entry change Cash? Start with an opening balance, then post an owner investment and a rent payment. Compare each highlighted Cash line with its ledger destination. Use Previous and Next to see which postings raise or lower the balance.",
  "aha": {
    "stateId": "both-posted",
    "observation": "Posting preserves the journal side: Cash debits increase the balance, while Cash credits decrease it."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "posting-rail",
      "kind": "step-rail",
      "presentation": "Place below the story and instructions. Show the active state and completed trace on this rail, without timing or automatic advancement.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "journal-and-ledger",
      "kind": "fixed-picture",
      "presentation": "Use the approved fixed-picture arrangement with journal rows left and Cash ledger regions right. Keep positions unchanged. Highlight bound active regions and connecting links. Inactive destinations are guides, not posted entries; readout labels identify posting status. Keep monetary values exclusively in readouts.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "posting-callout",
      "kind": "active-callout",
      "presentation": "Anchor the text beside its named target without covering labels. Present the reason as the bound status line beneath the picture.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "cash-measurements",
      "kind": "value-readout",
      "presentation": "Use four stable readout slots with wrapping labels. Values use whole USD, without rounding. Opening Cash is the reference balance. Current Cash equals opening Cash plus posted investment minus posted rent. Exclude unposted amounts from that calculation.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "presentation": "Provide Previous and Next buttons. Default index is zero; bounds are zero through four, increment one. Retain button names when disabled at boundaries. Each state persists until learner action, including both-posted. Use visible focus, accessible names, and keyboard activation. Navigation budget: one index control; parameter-control budget: zero.",
      "items": "variant.states",
      "label": "Posting state"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Reset restores the first state and all defaults. Provide visible focus, an accessible name, and keyboard activation.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Fixed USD example: opening debit balance, owner investment, and rent payment. Cash is an asset; assume no other activity, fees, or taxes.",
        "regions": [
          {
            "id": "investment-cash",
            "label": "Investment Cash",
            "values": [
              "Journal: debit Cash"
            ]
          },
          {
            "id": "owner-capital",
            "label": "Owner capital",
            "values": [
              "Journal: credit Owner capital"
            ]
          },
          {
            "id": "rent-expense",
            "label": "Rent expense",
            "values": [
              "Journal: debit Rent expense"
            ]
          },
          {
            "id": "rent-cash",
            "label": "Rent Cash",
            "values": [
              "Journal: credit Cash"
            ]
          },
          {
            "id": "cash-debit",
            "label": "Cash debit",
            "values": [
              "Ledger destination for Investment Cash"
            ]
          },
          {
            "id": "cash-credit",
            "label": "Cash credit",
            "values": [
              "Ledger destination for Rent Cash"
            ]
          },
          {
            "id": "cash-balance",
            "label": "Cash balance",
            "values": [
              "Cash ledger: debit-normal asset"
            ]
          }
        ],
        "links": [
          {
            "from": "investment-cash",
            "to": "cash-debit",
            "label": "Debit posts to debit"
          },
          {
            "from": "rent-cash",
            "to": "cash-credit",
            "label": "Credit posts to credit"
          }
        ],
        "states": [
          {
            "id": "opening",
            "label": "Opening Cash",
            "short": "Neither entry posted",
            "sentence": "Cash balance starts with an opening debit balance; both journal entries remain unposted.",
            "why": "The opening balance is the reference point for both postings.",
            "active": [
              "cash-balance"
            ],
            "calloutRegion": "cash-balance",
            "readouts": [
              {
                "id": "opening",
                "label": "Opening Cash",
                "value": "USD 1,000"
              },
              {
                "id": "investment",
                "label": "Investment debit · unposted",
                "value": "USD 500"
              },
              {
                "id": "rent",
                "label": "Rent credit · unposted",
                "value": "USD 200"
              },
              {
                "id": "balance",
                "label": "Current Cash · debit balance",
                "value": "USD 1,000"
              }
            ]
          },
          {
            "id": "inspect-investment",
            "label": "Find investment Cash",
            "short": "Inspect the journal debit",
            "sentence": "Investment Cash is the journal debit to post into Cash.",
            "why": "Owner capital is the matching credit, but it belongs in a different ledger account.",
            "active": [
              "investment-cash",
              "owner-capital"
            ],
            "calloutRegion": "investment-cash",
            "readouts": [
              {
                "id": "opening",
                "label": "Opening Cash",
                "value": "USD 1,000"
              },
              {
                "id": "investment",
                "label": "Investment debit · unposted",
                "value": "USD 500"
              },
              {
                "id": "rent",
                "label": "Rent credit · unposted",
                "value": "USD 200"
              },
              {
                "id": "balance",
                "label": "Current Cash · debit balance",
                "value": "USD 1,000"
              }
            ]
          },
          {
            "id": "investment-posted",
            "label": "Post the debit",
            "short": "Investment posted; Cash rises",
            "sentence": "Copy Investment Cash to Cash debit, preserving its amount and side.",
            "why": "Cash balance increases by the posted investment; the rent payment remains unposted.",
            "active": [
              "investment-cash",
              "cash-debit",
              "cash-balance"
            ],
            "calloutRegion": "cash-debit",
            "readouts": [
              {
                "id": "opening",
                "label": "Opening Cash",
                "value": "USD 1,000"
              },
              {
                "id": "investment",
                "label": "Investment debit · posted",
                "value": "USD 500"
              },
              {
                "id": "rent",
                "label": "Rent credit · unposted",
                "value": "USD 200"
              },
              {
                "id": "balance",
                "label": "Current Cash · debit balance",
                "value": "USD 1,500"
              }
            ]
          },
          {
            "id": "inspect-rent",
            "label": "Find rent Cash",
            "short": "Inspect the journal credit",
            "sentence": "Rent Cash is a credit, unlike the debit in Investment Cash.",
            "why": "Rent expense belongs in its own ledger; only the Cash line posts into Cash.",
            "active": [
              "rent-expense",
              "rent-cash"
            ],
            "calloutRegion": "rent-cash",
            "readouts": [
              {
                "id": "opening",
                "label": "Opening Cash",
                "value": "USD 1,000"
              },
              {
                "id": "investment",
                "label": "Investment debit · posted",
                "value": "USD 500"
              },
              {
                "id": "rent",
                "label": "Rent credit · unposted",
                "value": "USD 200"
              },
              {
                "id": "balance",
                "label": "Current Cash · debit balance",
                "value": "USD 1,500"
              }
            ]
          },
          {
            "id": "both-posted",
            "label": "Post the credit",
            "short": "Both posted; debit adds, credit subtracts",
            "sentence": "Copy Rent Cash to Cash credit; this posting lowers Cash balance.",
            "why": "Both postings preserve their journal sides: the investment debit adds to Cash, while the rent credit subtracts.",
            "active": [
              "rent-cash",
              "cash-debit",
              "cash-credit",
              "cash-balance"
            ],
            "calloutRegion": "cash-credit",
            "readouts": [
              {
                "id": "opening",
                "label": "Opening Cash",
                "value": "USD 1,000"
              },
              {
                "id": "investment",
                "label": "Investment debit · posted",
                "value": "USD 500"
              },
              {
                "id": "rent",
                "label": "Rent credit · posted",
                "value": "USD 200"
              },
              {
                "id": "balance",
                "label": "Current Cash · debit balance",
                "value": "USD 1,300"
              }
            ]
          }
        ]
      }
    ]
  }
}
